	node.Embed().IterateWrappers2(func(child Node) {
		ce := child.Embed()
		if ce.Bounds.Overlaps(r) {
			if !ce.HasAnyMarks(MarkNeedsPaint) {

				// improve selection with subchilds
				if r.In(ce.Bounds) {
					w := markIntersectingNodesNotNeedingPaint(child, r)
